TEXT ·sigmoidAVX2Kernel(SB), NOSPLIT, $0-24
	MOVQ src+0(FP), AX
	MOVQ dst+8(FP), CX
	MOVQ n+16(FP), DX

sig_loop:
	CMPQ         DX, $0x08
	JL           sig_tail
	VMOVUPS      (AX), Y0
	VXORPS       Y1, Y1, Y1
	VSUBPS       Y0, Y1, Y1
