	VADDPS       Y1, Y0, Y0
	VBROADCASTSS sig_p1<>+0(SB), Y1
	VADDPS       Y1, Y0, Y0
	VDIVPS       Y0, Y1, Y0
	VMOVUPS      Y0, (CX)
	ADDQ         $0x20, AX
	ADDQ         $0x20, CX
	SUBQ         $0x08, DX
	JMP          sig_loop

sig_tail:
	CMPQ   DX, $0x00
	JE     sig_done
	VMOVSS (AX), X0
	MOVSS  sig_p1<>+0(SB), X1
	MOVSS  sig_p1<>+0(SB), X2
	ADDSS  X2, X2
	SUBSS  X0, X2
	DIVSS  X2, X1
	VMOVSS X1, (CX)
